{"command": "# Verify env vars are actually accessible
for v in GITHUB_TOKEN RORK_PUBLIC_GITHUB_TOKEN IVX_OWNER_TOKEN IVX_OWNER_PASSWORD; do
  val=$(printenv "$v" 2>/dev/null)
  if [ -n "$val" ]; then
    echo "$v: SET (len=${#val}, prefix=${val:0:6}...)"
  else
    echo "$v: NOT_SET"
  fi
done
echo "---"
# Also check via bun
bun -e "
const keys = ['GITHUB_TOKEN','RORK_PUBLIC_GITHUB_TOKEN','IVX_OWNER_TOKEN','IVX_OWNER_PASSWORD'];
for (const k of keys) {
  const v = process.env[k];
  console.log(k + ':', v ? 'SET (len=' + v.length + ')' : 'NOT_SET');
}
" 2>&1"}

